New-AzNetworkInterface -Name 'nic-vm-jump' -ResourceGroupName 'sample-resourcegroupname' -Location 'eastus2' -SubnetId ((Get-AzVirtualNetwork -Name 'sample-vnetname' -ResourceGroupName 'sample-resourcegroupname').Subnets | Where-Object Name -eq 'snet-hosts').Id
Get-AzNetworkInterface -Name 'nic-vm-jump' -ResourceGroupName 'sample-resourcegroupname' | Set-AzNetworkInterfaceIpConfig -Name 'ipconfig1' -PublicIpAddress (Get-AzPublicIpAddress -Name 'sample-pipname' -ResourceGroupName 'sample-resourcegroupname') -Subnet ((Get-AzVirtualNetwork -Name 'sample-vnetname' -ResourceGroupName 'sample-resourcegroupname').Subnets | Where-Object Name -eq 'snet-hosts') | Set-AzNetworkInterface
